('ecoflow-delta-pro-ultra', 'EcoFlow DELTA Pro Ultra 6144Wh Whole-Home Solar Generator', 'solar', 2850000, 2790000, 2450000, 2, 52.0, '/assets/products/ecoflow-delta-pro-ultra.webp', 'Power your entire home during extended Nigerian grid outages. This beast delivers 7,200W of 240V AC output from a massive 6,144Wh LiFePO4 battery, expandable to 25kWh. Solar input of 5,600W means a full recharge in under 2 hours of peak sunlight.', 1, unixepoch('2026-06-16'), 1, 2450000, '/assets/products/ecoflow-delta-pro-ultra.webp', 2620000, 4.8, 1, 'EcoFlow', 1, 1),

