('anker-solix-f3800', 'Anker SOLIX F3800 3840Wh Portable Power Station with EV Charging', 'solar', 1850000, 1790000, 1580000, 3, 44.0, '/assets/products/anker-solix-f3800.webp', 'The first portable power station that can charge your electric vehicle. The F3800 features a NEMA 14-50 outlet for Level 2 EV charging, 6,000W surge capacity, and Anker''s InfiniPower technology with a 10-year lifespan on its LiFePO4 batteries.', 1, unixepoch('2026-06-16'), 1, 1580000, '/assets/products/anker-solix-f3800.webp', 1680000, 4.7, 1, 'Anker', 1, 1),

('jackery-explorer-2000-plus', 'Jackery Explorer 2000 Plus 2042Wh Solar Generator with 2x SolarSaga 200W', 'solar', 1250000, 1215000, 1050000, 4, 32.0, '/assets/products/jackery-explorer-2000-plus.webp', 'A complete solar ecosystem in one purchase. The 2,000W pure sine wave inverter powers refrigerators, power tools, and medical devices, while the included 400W of solar panels charge the 2,042Wh battery silently. Expandable to 12kWh for whole-home backup.', 1, unixepoch('2026-06-16'), 1, 1050000, '/assets/products/jackery-explorer-2000-plus.webp', 1150000, 4.7, 1, 'Jackery', 1, 1),

('ecoflow-wave-3-portable-ac', 'EcoFlow WAVE 3 Portable Air Conditioner with Battery - 6000 BTU', 'solar', 850000, 829000, 720000, 4, 19.5, '/assets/products/ecoflow-wave-3.webp', 'Beat the Nigerian heat anywhere with the world''s first portable battery-powered AC. The WAVE 3 delivers 6,000 BTU of cooling for up to 8 hours on its add-on battery, with solar charging capability and a dual-hose design that cools a room faster.', 1, unixepoch('2026-06-16'), 1, 720000, '/assets/products/ecoflow-wave-3.webp', 780000, 4.5, 0, 'EcoFlow', 1, 1),

