('goal-zero-yeti-3000x-pro', 'Goal Zero Yeti 3000X Pro 3032Wh Power Station with Home Integration Kit', 'solar', 1450000, 1420000, 1250000, 3, 36.5, '/assets/products/goal-zero-yeti-3000x.webp', 'Seamlessly integrate solar backup into your home''s electrical panel with the included Home Integration Kit. The Yeti 3000X Pro delivers 2,000W AC pure sine wave, with a 3,500W surge for starting motors and pumps. The MPPT charge controller maximizes solar harvest.', 1, unixepoch('2026-06-16'), 1, 1250000, '/assets/products/goal-zero-yeti-3000x.webp', 1350000, 4.6, 0, 'Goal Zero', 1, 1),

