('zendure-superbase-v6400', 'Zendure SuperBase V6400 6438Wh Portable Power Station with Satellite Battery', 'solar', 2250000, 2190000, 1920000, 2, 65.0, '/assets/products/zendure-superbase-v.webp', 'The world''s first portable power station with a hot-swappable satellite battery that extends runtime without shutting down. The V6400 delivers 3,800W output with 240V split-phase, dual MPPT controllers for 3,000W solar input, and motorized wheels for easy movement.', 1, unixepoch('2026-06-16'), 1, 1920000, '/assets/products/zendure-superbase-v.webp', 2080000, 4.6, 0, 'Zendure', 1, 1),

